public struct SearchListParams {
    /**
     * Current page of the collection.
     * Default: `1`
     */
    public let page: UInt32?
    /**
     * Maximum number of items to be returned in result set.
     * Default: `10`
     */
    public let perPage: UInt32?
    /**
     * Limit results to those matching a string.
     */
    public let search: String?
    /**
     * Limit results to items of an object type.
     * Default: `post`
     * One of: `post`, `term`, `post-format`
     */
    public let objectType: SearchResultType?
    /**
     * Limit results to items of one or more object subtypes.
     * Default: `any`
     */
    public let objectSubtype: SearchResultSubtype?
    /**
     * Ensure result set excludes specific IDs.
     */
    public let exclude: [Int64]
    /**
     * Limit result set to specific IDs.
     */
    public let include: [Int64]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
