         */page: UInt32? = nil, 
        /**
         * Maximum number of items to be returned in result set.
         * Default: `10`
         */perPage: UInt32? = nil, 
        /**
         * Limit results to those matching a string.
         */search: String? = nil, 
        /**
         * Limit results to items of an object type.
         * Default: `post`
         * One of: `post`, `term`, `post-format`
         */objectType: SearchResultType? = nil, 
        /**
         * Limit results to items of one or more object subtypes.
         * Default: `any`
         */objectSubtype: SearchResultSubtype? = nil, 
        /**
         * Ensure result set excludes specific IDs.
         */exclude: [Int64] = [], 
        /**
         * Limit result set to specific IDs.
         */include: [Int64] = []) {
        self.page = page
        self.perPage = perPage
        self.search = search
        self.objectType = objectType
        self.objectSubtype = objectSubtype
        self.exclude = exclude
        self.include = include
    }
}

