public enum RequestExecutionErrorReason {
    
    case invalidSslError(reason: InvalidSslErrorReason
    )
    case nonExistentSiteError(errorMessage: String?, suggestedAction: String?
    )
    case httpAuthenticationRequiredError(hostname: String, method: HttpAuthMethod?
    )
    case httpAuthenticationRejectedError(hostname: String, method: HttpAuthMethod?
    )
    case httpForbiddenError(hostname: String
    )
    case httpTimeoutError
    case misconfiguredHttpAuthenticationError(issue: HttpAuthMethodParsingError
    )
    case misconfiguredRateLimitError
    case deviceIsOfflineError(errorMessage: String
    )
    case genericError(errorMessage: String
    )
}


#if compiler(>=6)
extension RequestExecutionErrorReason: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeRequestExecutionErrorReason: FfiConverterRustBuffer {
    typealias SwiftType = RequestExecutionErrorReason

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RequestExecutionErrorReason {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .invalidSslError(reason: try FfiConverterTypeInvalidSslErrorReason.read(from: &buf)
        )
        
        case 2: return .nonExistentSiteError(errorMessage: try FfiConverterOptionString.read(from: &buf), suggestedAction: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 3: return .httpAuthenticationRequiredError(hostname: try FfiConverterString.read(from: &buf), method: try FfiConverterOptionTypeHttpAuthMethod.read(from: &buf)
        )
        
        case 4: return .httpAuthenticationRejectedError(hostname: try FfiConverterString.read(from: &buf), method: try FfiConverterOptionTypeHttpAuthMethod.read(from: &buf)
        )
        
        case 5: return .httpForbiddenError(hostname: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .httpTimeoutError
        
        case 7: return .misconfiguredHttpAuthenticationError(issue: try FfiConverterTypeHttpAuthMethodParsingError.read(from: &buf)
        )
        
        case 8: return .misconfiguredRateLimitError
        
        case 9: return .deviceIsOfflineError(errorMessage: try FfiConverterString.read(from: &buf)
        )
        
        case 10: return .genericError(errorMessage: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RequestExecutionErrorReason, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .invalidSslError(reason):
            writeInt(&buf, Int32(1))
            FfiConverterTypeInvalidSslErrorReason.write(reason, into: &buf)
            
        
        case let .nonExistentSiteError(errorMessage,suggestedAction):
            writeInt(&buf, Int32(2))
            FfiConverterOptionString.write(errorMessage, into: &buf)
            FfiConverterOptionString.write(suggestedAction, into: &buf)
            
        
        case let .httpAuthenticationRequiredError(hostname,method):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(hostname, into: &buf)
            FfiConverterOptionTypeHttpAuthMethod.write(method, into: &buf)
            
        
        case let .httpAuthenticationRejectedError(hostname,method):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(hostname, into: &buf)
            FfiConverterOptionTypeHttpAuthMethod.write(method, into: &buf)
            
        
        case let .httpForbiddenError(hostname):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(hostname, into: &buf)
            
        
        case .httpTimeoutError:
            writeInt(&buf, Int32(6))
        
        
        case let .misconfiguredHttpAuthenticationError(issue):
            writeInt(&buf, Int32(7))
            FfiConverterTypeHttpAuthMethodParsingError.write(issue, into: &buf)
            
        
        case .misconfiguredRateLimitError:
            writeInt(&buf, Int32(8))
        
        
        case let .deviceIsOfflineError(errorMessage):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(errorMessage, into: &buf)
            
        
        case let .genericError(errorMessage):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(errorMessage, into: &buf)
            
        }
    }
